From c44aad16c7da31626bb42085a68aae22c0a7ea6c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:16:21 +0100
Subject: [PATCH] applet: let the user cancel a connection that is still in
 progress

While a device was connecting the applet only showed a busy indicator
and ignored clicks, so a wrong or unreachable device kept connecting.
Now its Disconnect button stays visible and cancels the connection.

BUG: 449018
---
 src/applet/devicesstateproxymodel.cpp | 16 ++++++++++++++++
 src/applet/qml/DeviceItem.qml         |  9 +++++----
 2 files changed, 21 insertions(+), 4 deletions(-)

diff --git a/src/applet/devicesstateproxymodel.cpp b/src/applet/devicesstateproxymodel.cpp
index e00ffab6..e8e32633 100644
--- a/src/applet/devicesstateproxymodel.cpp
+++ b/src/applet/devicesstateproxymodel.cpp
@@ -13,6 +13,7 @@
 #include <KNotification>

 #include <algorithm>
+#include <utility>

 DevicesStateProxyModel::DevicesStateProxyModel(QObject *parent)
     : QIdentityProxyModel(parent)
@@ -105,7 +106,22 @@ void DevicesStateProxyModel::registerDisconnectingCallForDeviceUbi(BluezQt::Pend
     }

     auto &state = this->state(index);
+    const auto wasConnectingGlobal = isConnecting();
+
+    // Disconnecting cancels a pending connection attempt, so its failure is expected and not reported
+    const auto cancelledCalls = std::exchange(state.connectingCalls, {});
+    for (const auto cancelledCall : cancelledCalls) {
+        disconnect(cancelledCall, &BluezQt::PendingCall::finished, this, &DevicesStateProxyModel::handlePendingCallFinished);
+    }
+
     registerPendingCall(call, index, state.disconnectingCalls);
+
+    if (!cancelledCalls.isEmpty()) {
+        Q_EMIT dataChanged(index, index, {ConnectingRole});
+    }
+    if (wasConnectingGlobal != isConnecting()) {
+        Q_EMIT connectingChanged();
+    }
 }

 void DevicesStateProxyModel::registerPendingCall(BluezQt::PendingCall *call, const QModelIndex &index, QSet<BluezQt::PendingCall *> &calls)
diff --git a/src/applet/qml/DeviceItem.qml b/src/applet/qml/DeviceItem.qml
index e750926a..9dfdaacc 100644
--- a/src/applet/qml/DeviceItem.qml
+++ b/src/applet/qml/DeviceItem.qml
@@ -35,9 +35,10 @@ PlasmaExtras.ExpandableListItem {
     title: model.DeviceFullName
     subtitle: infoText()
     isBusy: model.Connecting || model.Disconnecting
+    showDefaultActionButtonWhenBusy: model.Connecting
     defaultActionButtonAction: QQC2.Action {
-        icon.name: root.model.Connected ? "network-disconnect-symbolic" : "network-connect-symbolic"
-        text: root.model.Connected ? i18n("Disconnect") : i18n("Connect")
+        icon.name: root.model.Connected || root.model.Connecting ? "network-disconnect-symbolic" : "network-connect-symbolic"
+        text: root.model.Connected || root.model.Connecting ? i18n("Disconnect") : i18n("Connect")
         onTriggered: source => {
             root.toggleDevice();
         }
@@ -325,11 +326,11 @@ PlasmaExtras.ExpandableListItem {
     }

     function toggleDevice(): void {
-        if (model.Connecting || model.Disconnecting) {
+        if (model.Disconnecting) {
             return;
         }

-        if (model.Connected) {
+        if (model.Connected || model.Connecting) {
             const call = model.Device.disconnectFromDevice();
             PlasmaBt.SharedDevicesStateProxyModel.registerDisconnectingCallForDeviceUbi(call, model.Ubi);
         } else {
